def strip_page_titles(pages):
    return [{key: value for key, value in page.items() if key != "title_en"} for page in pages or []]


def drop_english_page_titles(apps, schema_editor):
    # the `pages` JSON of the home blocks (and of the published version) kept a title_en per page
    HomeBlock = apps.get_model("service", "HomeBlock")
    HomePage = apps.get_model("service", "HomePage")
    for block in HomeBlock.objects.exclude(pages=None):
        if block.pages:
            block.pages = strip_page_titles(block.pages)
            block.save(update_fields=["pages"])
    for page in HomePage.objects.exclude(published_data=None):
        for block in (page.published_data or {}).get("blocks", []):
            block.pop("title_en", None)
            if block.get("pages"):
                block["pages"] = strip_page_titles(block["pages"])
        page.save(update_fields=["published_data"])


